{
  "identity": {
    "name": "Treasure Valley IT",
    "location": "Boise, Idaho",
    "claims": [
      {
        "statement": "The business operates under the name Treasure Valley IT.",
        "label": "fact",
        "sourceUrl": "https://www.tvit.net/",
        "quote": "At Treasure Valley IT, our mission is to deliver exceptional service by dedicating our full attention to each client's unique needs."
      },
      {
        "statement": "The company's main office is located in Boise, Idaho.",
        "label": "fact",
        "sourceUrl": "https://www.tvit.net/",
        "quote": "Main Office: 9019 W Barnes St Boise ID 83709"
      },
      {
        "statement": "The business has been operating in the Boise area for approximately two decades.",
        "label": "fact",
        "sourceUrl": "https://www.tvit.net/managed-it-services-boise/",
        "quote": "19+ Years in business"
      }
    ]
  },
  "industry": {
    "industry": "Information Technology / Managed IT Services (MSP) & Cybersecurity",
    "activities": [
      "Managed IT services",
      "Cybersecurity and compliance management",
      "Network infrastructure configuration and maintenance",
      "Cloud services and data backup/disaster recovery",
      "IT consulting and strategy",
      "24/7 technical helpdesk and on-site support",
      "Residential computer setup and repair"
    ],
    "claims": [
      {
        "statement": "Treasure Valley IT provides comprehensive IT solutions for commercial businesses and residential customers.",
        "label": "fact",
        "sourceUrl": "https://www.tvit.net/",
        "quote": "We provide comprehensive IT services for both businesses and residential clients."
      },
      {
        "statement": "The company provides fully managed IT as well as co-managed IT support tiers.",
        "label": "fact",
        "sourceUrl": "https://www.tvit.net/",
        "quote": "We offer fully managed IT services as well as co-managed IT with different tiers of support."
      },
      {
        "statement": "The business serves corporate and organizational clients across diverse vertical markets rather than operating as a home-service contractor.",
        "label": "inference",
        "sourceUrl": "https://www.tvit.net/",
        "quote": null
      }
    ]
  },
  "publicInformation": {
    "officialWebsite": "https://www.tvit.net/",
    "claims": [
      {
        "statement": "The official website provides details on IT infrastructure, cybersecurity, client support forms, and service areas.",
        "label": "fact",
        "sourceUrl": "https://www.tvit.net/",
        "quote": "Managed IT Services IT Infrastructure Services Software and Productivity Services Cybersecurity & Compliance Solutions Commercial IT"
      },
      {
        "statement": "The company serves Boise, Eagle, Kuna, Nampa, Garden City, Middleton, Meridian, Star, Caldwell, and surrounding areas in Idaho.",
        "label": "fact",
        "sourceUrl": "https://www.tvit.net/",
        "quote": "We are proud to serve Boise, Idaho and the surrounding areas, including: Boise Eagle Kuna Nampa Garden City Middleton Meridian Star Caldwell"
      },
      {
        "statement": "The company indicates membership in the Idaho Veterans Chamber of Commerce.",
        "label": "fact",
        "sourceUrl": "https://www.tvit.net/about/",
        "quote": "At Treasure Valley IT, we are honored to be proud members of the Idaho Veterans Chamber of Commerce"
      }
    ]
  },
  "licensing": {
    "claims": [
      {
        "statement": "The company asserts copyright ownership on its website materials.",
        "label": "fact",
        "sourceUrl": "https://www.tvit.net/",
        "quote": "Treasure Valley IT, All rights reserved © ."
      },
      {
        "statement": "As an IT managed services firm rather than a trade contractor, trade licensing (such as electrical or plumbing contractor licenses) is not listed on the website.",
        "label": "inference",
        "sourceUrl": "https://www.tvit.net/",
        "quote": null
      }
    ],
    "limitations": "The public website does not display a state business registration entity ID number or specific regulatory licenses."
  },
  "existingSoftware": [
    {
      "product": "Google Tag Manager",
      "purpose": "Website tag management and tracking deployment",
      "evidence": {
        "statement": "The website loads Google Tag Manager via an iframe container.",
        "label": "inference",
        "sourceUrl": "https://www.tvit.net/",
        "quote": null
      }
    },
    {
      "product": "Cloudflare Insights",
      "purpose": "Web performance and analytics monitoring",
      "evidence": {
        "statement": "The site executes Cloudflare Insights analytics script.",
        "label": "inference",
        "sourceUrl": "https://www.tvit.net/",
        "quote": null
      }
    },
    {
      "product": "Partner & Vendor Technology Stack (Microsoft, Dell, Fortinet, Acronis, MailProtector)",
      "purpose": "Enterprise IT, security, backup, and productivity management for clients",
      "evidence": {
        "statement": "The company lists key technology vendor partners and platforms it deploys.",
        "label": "fact",
        "sourceUrl": "https://www.tvit.net/",
        "quote": "Dell Technologies Verizon One Talk Acronis Apple MailProtector Microsoft Lenovo Fortinet"
      }
    }
  ],
  "opportunityEvidence": [
    {
      "statement": "The company operates an online client ticketing system and onboarding portal for IT service intake.",
      "label": "fact",
      "sourceUrl": "https://www.tvit.net/",
      "quote": "Pay Bill Client Portal Submit a Service Ticket Onboarding Form New PC Setup New PC Setup with Migration"
    }
  ],
  "problems": [
    {
      "problem": "Potential manual routing of incoming website service requests and onboarding submissions.",
      "label": "hypothesis",
      "basis": "The website provides web forms for tickets and PC onboarding, which could theoretically involve manual handoffs, but no evidence suggests a current breakdown or dissatisfaction."
    }
  ],
  "existingSolutions": [
    {
      "solution": "Professional Services Automation (PSA) and Remote Monitoring & Management (RMM) ticketing systems standard to MSP operations (e.g., ConnectWise, Autotask, HaloPSA)",
      "addresses": "Service ticketing, client onboarding, dispatch, and automated client billing",
      "alreadyOwned": true
    }
  ],
  "forgexSolutions": [],
  "feasibility": {
    "rating": "not applicable",
    "explanation": "Treasure Valley IT is outside ForgeX's target market segment of home-service trade contractors. As an MSP, they already specialize in technical systems administration, IT infrastructure, and software management."
  },
  "aiDelivery": {
    "rating": "not applicable",
    "explanation": "No custom ForgeX automation or AI agent is recommended because the company does not fit ForgeX's target profile."
  },
  "humanReview": [],
  "risks": [
    {
      "type": "operational",
      "description": "Attempting to pitch home-service contractor operational workflows to a technical managed service provider represents a complete operational mismatch."
    }
  ],
  "commercial": {
    "supportable": false,
    "value": null,
    "implementationCost": null,
    "assumptions": [
      "The website does not publish public list prices for managed services, and Treasure Valley IT does not match ForgeX's target business profile."
    ]
  },
  "contacts": {
    "decisionMakerRoles": [
      "Owner",
      "Chief Executive Officer",
      "President",
      "General Manager"
    ],
    "people": [],
    "channels": [
      {
        "kind": "phone",
        "value": "[redacted]",
        "sourceUrl": "https://www.tvit.net/"
      },
      {
        "kind": "phone",
        "value": "[redacted]",
        "sourceUrl": "https://www.tvit.net/"
      },
      {
        "kind": "phone",
        "value": "[redacted]",
        "sourceUrl": "https://www.tvit.net/"
      },
      {
        "kind": "web form",
        "value": "https://www.tvit.net/",
        "sourceUrl": "https://www.tvit.net/"
      }
    ]
  },
  "discovery": {
    "questions": [],
    "outreachSubject": "",
    "outreachBody": ""
  },
  "evidence": {
    "sourcesUsed": [
      {
        "url": "https://www.tvit.net/",
        "usedFor": "Company identity, core services, vendor partners, office location, and primary phone contacts"
      },
      {
        "url": "https://www.tvit.net/about/",
        "usedFor": "Company founding background, mission, core values, and community affiliations"
      },
      {
        "url": "https://www.tvit.net/meet-our-team-treasure-valley-it/",
        "usedFor": "Review of leadership and organizational team structure"
      },
      {
        "url": "https://www.tvit.net/privacy-policy/",
        "usedFor": "Verification of corporate identity, data collection practices, and office address confirmation"
      },
      {
        "url": "https://www.tvit.net/managed-it-services-boise/",
        "usedFor": "Operational service scope, client metrics, years in business, and service features"
      }
    ],
    "limitations": [
      "Specific executive names and titles are not listed on the public 'Meet Our Team' or 'About' pages.",
      "The contact page (https://www.tvit.net/contact-us/) returned an automated HTTP 403 access restriction.",
      "Specific pricing schedules are not published openly on the website."
    ]
  },
  "qualification": {
    "category": "not a fit",
    "rationale": "ForgeX targets owner-led home-service contractors (HVAC, plumbing, and electrical) with 10 to 75 staff that pay for leads. Treasure Valley IT is a Managed IT Services Provider (MSP) and cybersecurity firm specializing in commercial network management, helpdesk support, and technical consulting. Because it is outside ForgeX's target vertical and operates as an IT technology firm itself, it is not a fit."
  }
}
